#include "exercise.h"
#include <assert.h>
#include <string.h>
#include <stdlib.h>
#include <math.h>
#include <stdio.h>
static bool positive(int x){return x>0;}
static bool bstring(const void*p){return (*(const char*const*)p)[0]==98;}
static void string_length(const void*p,void*out){*(size_t*)out=strlen(*(const char*const*)p);}
int main(void){
int m[26];assert(solve("SEND + MORE == MONEY",m));assert(m['S'-'A']==9&&m['E'-'A']==5&&m['N'-'A']==6&&m['D'-'A']==7&&m['M'-'A']==1&&m['O'-'A']==0&&m['R'-'A']==8&&m['Y'-'A']==2);assert(!solve("A == B",m));assert(solve("I + BB == ILL",m)&&m['I'-'A']==1&&m['B'-'A']==9);

return 0;}
